<?php $query=['q'=>$filters['search'],'status'=>$filters['account_status']]; $pageLink=static fn(int $target):string=>url('admin/customers?'.http_build_query(array_filter($query+['page'=>$target],static fn($value)=>$value!==''))); ?>
<section class="section dashboard-page"><div class="container"><div class="page-heading"><div><span class="eyebrow">Platform accounts</span><h1>Customers</h1><p class="muted"><?= e($total) ?> customer<?= $total===1?'':'s' ?>.</p></div><a class="button button-secondary" href="<?= e(url('admin/dashboard')) ?>">Dashboard</a></div>
<?php foreach($filterErrors as $message): ?><div class="alert alert-warning"><?= e($message) ?></div><?php endforeach; ?>
<form class="catalog-filters customer-management-filters" method="get"><div class="catalog-search-field"><label for="q">Search customers</label><input id="q" name="q" maxlength="100" value="<?= e($filters['search']) ?>" placeholder="Name, email, phone"></div><div><label for="status">Account status</label><select id="status" name="status"><?php foreach(['any','approved','pending','rejected','disabled'] as $value): ?><option value="<?= e($value) ?>" <?= $filters['account_status']===$value?'selected':'' ?>><?= e(ucfirst($value)) ?></option><?php endforeach; ?></select></div><div class="catalog-filter-actions"><button class="button button-compact">Apply filters</button><a class="button button-secondary button-compact" href="<?= e(url('admin/customers')) ?>">Reset</a></div></form>
<div class="panel"><?php if($customers===[]): ?><p class="muted">No customers match this filter.</p><?php else: ?><div class="responsive-table"><table><thead><tr><th>Customer</th><th>Contact</th><th>Status</th><th>Bookings</th><th>Confirmed tickets</th><th>Confirmed spend</th></tr></thead><tbody><?php foreach($customers as $customer): ?><tr><td><a href="<?= e(url('admin/customers/'.$customer['id'])) ?>"><strong><?= e($customer['name']) ?></strong></a><small>Joined <?= e(local_datetime($customer['created_at'],'d M Y')) ?></small></td><td><?= e($customer['email']) ?><small><?= e($customer['phone']) ?></small></td><td><span class="status-badge status-<?= e($customer['account_status']) ?>"><?= e($customer['account_status']) ?></span></td><td><?= e($customer['booking_count']) ?></td><td><?= e($customer['confirmed_tickets']) ?></td><td><?= e(money($customer['confirmed_spend'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php if($pageCount>1): ?><nav class="pagination"><?= $page>1?'<a href="'.e($pageLink($page-1)).'">&larr; Previous</a>':'<span></span>' ?><span>Page <?= e($page) ?> of <?= e($pageCount) ?></span><?= $page<$pageCount?'<a href="'.e($pageLink($page+1)).'">Next &rarr;</a>':'<span></span>' ?></nav><?php endif; ?>
</div></section>
